import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { ordersApi, couponsApi } from '../services/api';

const Checkout = () => {
    const location = useLocation();
    const navigate = useNavigate();

    const { subtotal, cartItems } = location.state || { subtotal: 0, cartItems: [] };

    const [provinces, setProvinces] = useState([]);
    const [districts, setDistricts] = useState([]);
    const [wards, setWards] = useState([]);

    const [selectedProvince, setSelectedProvince] = useState({ code: '', name: '' });
    const [selectedDistrict, setSelectedDistrict] = useState({ code: '', name: '' });
    const [selectedWard, setSelectedWard] = useState({ code: '', name: '' });
    const [addressDetail, setAddressDetail] = useState('');

    const [couponCode, setCouponCode] = useState('');
    const [discount, setDiscount] = useState(0);
    const [shippingFee, setShippingFee] = useState(0);
    const [distanceKm, setDistanceKm] = useState(0);
    const [isCalculatingShip, setIsCalculatingShip] = useState(false);

    // TỔNG TIỀN VNĐ
    const totalAmount = subtotal - discount + shippingFee;

    const [formData, setFormData] = useState({
        name: '', phone: '', email: '', notes: ''
    });
    const [paymentMethod, setPaymentMethod] = useState('Cash On Delivery');

    const handleInputChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    useEffect(() => {
        fetch('https://provinces.open-api.vn/api/p/')
            .then(res => res.json())
            .then(data => setProvinces(data))
            .catch(err => console.log("Lỗi tải tỉnh thành", err));
    }, []);

    const handleProvinceChange = (e) => {
        const pCode = e.target.value;
        const pName = e.target.options[e.target.selectedIndex].text;
        setSelectedProvince({ code: pCode, name: pName });
        setSelectedDistrict({ code: '', name: '' });
        setSelectedWard({ code: '', name: '' });
        setDistricts([]);
        setWards([]);
        setShippingFee(0);

        if (pCode) {
            fetch(`https://provinces.open-api.vn/api/p/${pCode}?depth=2`)
                .then(res => res.json())
                .then(data => setDistricts(data.districts));
        }
    };

    const handleDistrictChange = (e) => {
        const dCode = e.target.value;
        const dName = e.target.options[e.target.selectedIndex].text;
        setSelectedDistrict({ code: dCode, name: dName });
        setSelectedWard({ code: '', name: '' });
        setWards([]);
        setShippingFee(0);

        if (dCode) {
            fetch(`https://provinces.open-api.vn/api/d/${dCode}?depth=2`)
                .then(res => res.json())
                .then(data => setWards(data.wards));
        }
    };

    const handleWardChange = (e) => {
        const wCode = e.target.value;
        const wName = e.target.options[e.target.selectedIndex].text;
        setSelectedWard({ code: wCode, name: wName });
    };

    const calculateDistanceInKm = (lat1, lon1, lat2, lon2) => {
        const R = 6371;
        const dLat = (lat2 - lat1) * (Math.PI / 180);
        const dLon = (lon2 - lon1) * (Math.PI / 180);
        const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        return R * c;
    };

    // TỰ ĐỘNG TÍNH SHIP BẰNG TIỀN VIỆT THEO TỌA ĐỘ
    useEffect(() => {
        if (selectedProvince.name && selectedDistrict.name && selectedWard.name) {
            const autoCalculateShipping = async () => {
                setIsCalculatingShip(true);
                const fullAddress = `${selectedWard.name}, ${selectedDistrict.name}, ${selectedProvince.name}, Vietnam`;

                try {
                    const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(fullAddress)}`);
                    const data = await response.json();

                    if (data && data.length > 0) {
                        const customerLat = parseFloat(data[0].lat);
                        const customerLon = parseFloat(data[0].lon);
                        const shopLat = 21.046386;
                        const shopLon = 105.795495;

                        const distance = calculateDistanceInKm(shopLat, shopLon, customerLat, customerLon);
                        setDistanceKm(distance);

                        // PHÍ SHIP: Mặc định 15k, cộng 5k mỗi km. Tối đa 150k.
                        let calculatedFee = 15000 + Math.round(distance) * 5000;
                        if (distance < 2) calculatedFee = 15000;
                        if (calculatedFee > 150000) calculatedFee = 150000;

                        setShippingFee(calculatedFee);
                    } else {
                        setShippingFee(30000); // Không tra ra được thì mặc định 30k
                    }
                } catch (error) {
                    setShippingFee(30000);
                } finally {
                    setIsCalculatingShip(false);
                }
            };
            autoCalculateShipping();
        }
    }, [selectedWard.name]);

    const handleApplyCoupon = async () => {
        if (!couponCode) {
            alert("Ní vui lòng nhập mã giảm giá trước nhé!");
            return;
        }
        try {
            const response = await couponsApi.check(couponCode);
            const data = response.data;
            const phanTramGiam = data.discountPercent / 100;
            setDiscount(subtotal * phanTramGiam);
            alert(`Áp dụng thành công! Giảm ${data.discountPercent}% cho đơn hàng. 🌟`);
        } catch (error) {
            setDiscount(0);
            alert(error.response?.data || "Mã giảm giá không hợp lệ hoặc đã hết hạn!");
        }
    };

    const handlePlaceOrder = async (e) => {
        e.preventDefault();

        if (!selectedWard.name || !addressDetail) {
            alert("Ní vui lòng chọn đầy đủ Tỉnh/Thành, Quận/Huyện, Phường/Xã và Số nhà nhé!");
            return;
        }

        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert("Vui lòng đăng nhập tài khoản để đặt hàng!");
            navigate('/login');
            return;
        }

        const fullShippingAddress = `${addressDetail}, ${selectedWard.name}, ${selectedDistrict.name}, ${selectedProvince.name} (KM: ${distanceKm.toFixed(1)})`;

        const orderData = {
            userId: currentUserId,
            shippingAddress: fullShippingAddress,
            phone: formData.phone,
            orderNotes: formData.notes,
            paymentMethod: paymentMethod,
            subTotal: subtotal,
            shippingFee: shippingFee,
            discountAmount: discount,
            totalAmount: totalAmount,
            couponCode: couponCode,
            details: cartItems.map(item => ({
                productId: item.productId || item.id,
                quantity: item.quantity,
                unitPrice: item.discountPrice || item.price
            }))
        };

        try {
            await ordersApi.checkout(orderData);
            alert("🎉 Đặt hàng thành công! Đơn hàng của ní đang chờ hệ thống xử lý.");
            navigate('/my-orders');
        } catch (error) {
            alert(`Đặt hàng thất bại: ${error.response?.data || "Lỗi máy chủ C#!"}`);
        }
    };

    return (

        <>
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Thanh Toán Đơn Hàng</h1>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <form onSubmit={handlePlaceOrder}>
                        <div className="row g-5">
                            <div className="col-md-12 col-lg-6 col-xl-7">
                                <h2 className="mb-4">Thông tin giao hàng</h2>
                                <div className="row">
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100 mb-3">
                                            <label className="form-label mb-2">Họ và Tên người nhận<sup>*</sup></label>
                                            <input type="text" name="name" className="form-control" onChange={handleInputChange} required />
                                        </div>
                                    </div>
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100 mb-3">
                                            <label className="form-label mb-2">Số điện thoại<sup>*</sup></label>
                                            <input type="text" name="phone" className="form-control" onChange={handleInputChange} required />
                                        </div>
                                    </div>
                                </div>

                                <div className="row">
                                    <div className="col-md-4 mb-3">
                                        <label className="form-label mb-2">Tỉnh / Thành phố <sup>*</sup></label>
                                        <select className="form-select border-warning" onChange={handleProvinceChange} value={selectedProvince.code} required>
                                            <option value="">-- Chọn Tỉnh --</option>
                                            {provinces.map(p => (
                                                <option key={p.code} value={p.code}>{p.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="col-md-4 mb-3">
                                        <label className="form-label mb-2">Quận / Huyện <sup>*</sup></label>
                                        <select className="form-select border-warning" onChange={handleDistrictChange} value={selectedDistrict.code} disabled={!selectedProvince.code} required>
                                            <option value="">-- Chọn Quận --</option>
                                            {districts.map(d => (
                                                <option key={d.code} value={d.code}>{d.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="col-md-4 mb-3">
                                        <label className="form-label mb-2">Phường / Xã <sup>*</sup></label>
                                        <select className="form-select border-warning" onChange={handleWardChange} value={selectedWard.code} disabled={!selectedDistrict.code} required>
                                            <option value="">-- Chọn Phường --</option>
                                            {wards.map(w => (
                                                <option key={w.code} value={w.code}>{w.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                <div className="form-item mb-4">
                                    <label className="form-label mb-2">Số nhà, Tên đường <sup>*</sup></label>
                                    <input type="text" className="form-control border-warning" placeholder="Ví dụ: Số 236 đường Hoàng Quốc Việt..." value={addressDetail} onChange={(e) => setAddressDetail(e.target.value)} required />
                                </div>

                                <div className="form-item mb-4">
                                    <textarea name="notes" className="form-control" rows="3" placeholder="Ghi chú cho Shipper (Tùy chọn)..." onChange={handleInputChange}></textarea>
                                </div>

                                <h2 className="mb-4 mt-5">Phương thức thanh toán</h2>
                                <div className="p-4 bg-light rounded border">
                                    <div className="form-check mb-3">
                                        <input className="form-check-input" type="radio" name="payment" id="cod" value="Cash On Delivery" checked={paymentMethod === 'Cash On Delivery'} onChange={(e) => setPaymentMethod(e.target.value)} />
                                        <label className="form-check-label fw-bold" htmlFor="cod">Thanh toán khi nhận hàng (COD)</label>
                                    </div>
                                    <div className="form-check mb-3">
                                        <input className="form-check-input" type="radio" name="payment" id="momo" value="MoMo" checked={paymentMethod === 'MoMo'} onChange={(e) => setPaymentMethod(e.target.value)} />
                                        <label className="form-check-label fw-bold" htmlFor="momo">Thanh toán qua Ví điện tử MoMo</label>
                                    </div>
                                    <div className="form-check">
                                        <input className="form-check-input" type="radio" name="payment" id="bank" value="Bank Transfer" checked={paymentMethod === 'Bank Transfer'} onChange={(e) => setPaymentMethod(e.target.value)} />
                                        <label className="form-check-label fw-bold" htmlFor="bank">Chuyển khoản Ngân hàng (Quét mã QR)</label>
                                    </div>

                                    {/* MÃ QR ĐÃ SỬA THÀNH VNĐ CHUẨN */}
                                    {paymentMethod === 'Bank Transfer' && (
                                        <div className="mt-4 text-center bg-white p-3 rounded border border-info">
                                            <h5 className="text-info mb-3">Quét mã QR để thanh toán tự động</h5>
                                            <p className="small text-muted mb-2">Ngân hàng MB Bank - Chủ TK: TRAN VAN TINH</p>
                                            <img src={`https://img.vietqr.io/image/mbbank-0999888777-compact2.png?amount=${Math.round(totalAmount)}&addInfo=ThanhToanFruitables`} alt="QR Code Ngân Hàng" style={{ width: '200px' }} />
                                            <p className="mt-2 fw-bold text-danger">Tổng thanh toán: {totalAmount.toLocaleString('vi-VN')} VNĐ</p>
                                        </div>
                                    )}

                                    {paymentMethod === 'MoMo' && (
                                        <div className="mt-4 text-center bg-white p-3 rounded border" style={{ borderColor: '#A50064' }}>
                                            <h5 className="mb-3" style={{ color: '#A50064' }}>Mở ứng dụng MoMo để quét mã</h5>
                                            <img src="https://upload.wikimedia.org/wikipedia/commons/d/d0/QR_code_for_mobile_English_Wikipedia.svg" alt="MoMo QR" style={{ width: '150px', border: '5px solid #A50064', borderRadius: '10px' }} />
                                            <p className="mt-2 fw-bold text-danger">Tổng thanh toán: {totalAmount.toLocaleString('vi-VN')} VNĐ</p>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="col-md-12 col-lg-6 col-xl-5">
                                <div className="table-responsive bg-light rounded p-5 border">
                                    <h2 className="display-6 mb-4" style={{ fontSize: '26px' }}>Hóa đơn đơn hàng</h2>

                                    <div className="input-group mb-4">
                                        <input type="text" className="form-control py-3" placeholder="Nhập mã giảm giá..." value={couponCode} onChange={(e) => setCouponCode(e.target.value)} />
                                        <button className="btn btn-warning fw-bold text-dark px-4" type="button" onClick={handleApplyCoupon}>ÁP DỤNG</button>
                                    </div>

                                    <table className="table align-middle mt-2">
                                        <thead>
                                            <tr>
                                                <th scope="col">Hình</th>
                                                <th scope="col">Sản phẩm</th>
                                                <th scope="col">Thành tiền</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {cartItems.map((item, index) => {
                                                const finalPrice = item.discountPrice || item.price;
                                                return (
                                                    <tr key={index}>
                                                        <td><img src={item.imageUrl || '/img/avatar.jpg'} style={{ width: '45px', height: '45px', objectFit: 'cover', borderRadius: '50%' }} alt="" /></td>
                                                        <td>{item.name} <span className="text-muted fw-bold">x{item.quantity}</span></td>
                                                        <td className="fw-bold">{(finalPrice * item.quantity).toLocaleString('vi-VN')} đ</td>
                                                    </tr>
                                                )
                                            })}
                                            <tr className="border-top">
                                                <td colSpan="2"><strong>Tổng tiền hàng:</strong></td>
                                                <td className="fw-bold">{subtotal.toLocaleString('vi-VN')} đ</td>
                                            </tr>

                                            {discount > 0 && (
                                                <tr className="text-success">
                                                    <td colSpan="2"><strong>Khấu trừ mã giảm giá:</strong></td>
                                                    <td className="fw-bold">-{discount.toLocaleString('vi-VN')} đ</td>
                                                </tr>
                                            )}

                                            <tr>
                                                <td colSpan="2">
                                                    <strong>Phí vận chuyển:</strong><br />
                                                    {isCalculatingShip ? (
                                                        <small className="text-warning fw-bold"><i className="fa fa-spinner fa-spin me-1"></i>Đang tính phí...</small>
                                                    ) : shippingFee === 0 ? (
                                                        <small className="text-danger fw-bold">*Chọn địa chỉ để tính phí</small>
                                                    ) : (
                                                        <small className="text-success fw-bold">Khoảng cách: {distanceKm.toFixed(1)} km</small>
                                                    )}
                                                </td>
                                                <td>
                                                    <strong className={shippingFee === 0 ? "text-danger" : "text-dark"}>
                                                        {shippingFee === 0 ? "---" : `${shippingFee.toLocaleString('vi-VN')} đ`}
                                                    </strong>
                                                </td>
                                            </tr>

                                            <tr className="border-top border-dark border-2 bg-white">
                                                <td colSpan="2"><h5 className="mb-0 text-primary fw-bold">TỔNG THANH TOÁN:</h5></td>
                                                <td><h5 className="mb-0 text-danger fw-bold">{totalAmount.toLocaleString('vi-VN')} đ</h5></td>
                                            </tr>
                                        </tbody>
                                    </table>

                                    <button
                                        type="submit"
                                        className="btn border-secondary bg-primary text-white py-3 px-4 text-uppercase w-100 fw-bold mt-4"
                                        disabled={shippingFee === 0 || isCalculatingShip}
                                    >
                                        {isCalculatingShip ? 'ĐANG TÍNH TIỀN...' : 'XÁC NHẬN ĐẶT HÀNG NGAY'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </form>
                </div>
            </div>
        </>
    );
};

export default Checkout;
